/*
 * standard-delivery contract.js: the contract table of the
 * standard-delivery workflow, one row per step rule.
 *
 * Outputs
 *   contractRows()  an array of {id, step, check, rule}: id is SD-NN, step
 *                   the step the rule governs, check the function of the
 *                   built script that enforces it, and rule one sentence.
 *
 * Invariants
 *   Each row has one test in tests/workflow-scripts/standard-delivery.test.mjs,
 *   which loads this file with loadLibs and requires each check to be a
 *   function of the built script, not of main.js: a check can live in main.js
 *   or in any module the build bundles.
 *   The build bundles every .js file of this directory but this one, so this
 *   file never reaches the built script.
 *
 * Why
 *   The rows are test data, so keeping them out of the built script leaves
 *   its character budget to the code that runs.
 */

function contractRows() {
  return [
    { id: 'SD-01', step: 'Launch', check: 'readDeliveryLaunch', rule: 'The request is a non-blank string, trunk and references are read through args.js, whose resume_args guard refuses args that hold a resume_args key and whose build check refuses a resume of another build, and the trunk passes isGitIdentifier, or the run blocks before any agent call.' },
    { id: 'SD-02', step: 'Facts', check: 'checkDeliveryFacts', rule: 'The facts runner runs the gather-facts command, --trunk and then --ref with each reference, with no --remote, from its command block, and RELAY_SCHEMA, not the prompt, says to relay its outcome and stdout word for word; a relay that is blocked or fails its schema or gatherFactsRoutingSpec() stops through stopDelivery with isReplan true, so it pauses with the fix line brief and the reply starts a new pass from the facts step with the answers block, outside maxReplans(), and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-03', step: 'Facts', check: 'isConsistentFactsRelay', rule: 'The relayed lines agree with each other and with the launch trunk, or the run blocks as malformed facts.' },
    { id: 'SD-04', step: 'Facts', check: 'checkDeliveryFacts', rule: 'A cut other than none pauses the run before the scan and before planning, naming the fields cut, and the reply starts a new pass from the facts step.' },
    { id: 'SD-05', step: 'Facts to plan', check: 'describeDeliveryStops', rule: 'A delivery stop pauses the run before planning, naming each stop in fixed plain wording, at most maxListedItems() stop lines then a count of the rest, and the reply starts a new pass from the facts step; dirty paths say the run never commits, stashes or discards an edit it did not make.' },
    { id: 'SD-06', step: 'Scan', check: 'runPassScan', rule: 'When external_texts is above 0 the shared scan step runs on model sonnet before planning: a scan that fits its schema and flags an injection suspect is a terminal cause that ends the run, and a coverage failure or a result that fails its schema pauses with the fix line brief; runPassScan returns its cause or undefined on every pass, and on pass 1 it calls agent() with the prompt, options and label scan of lib/facts.js runScanStep, byte for byte, so a resumed run replays the cached result, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-07', step: 'Plan', check: 'runDeliveryPass', rule: 'Every planner call follows the facts step of its own pass, and a pass starts only at launch, after needs_replan, after a branch switch, after a taken local review escalation or root cluster, after a reply to a tail ask other than a local review question, or after a reply to a stop with isReplan true, which counts against no replan limit; a taken local review call starts no pass.' },
    { id: 'SD-08', step: 'Plan', check: 'describePlanProblem', rule: 'The plan result fits the schema of its call, the plan result schema or on a revise pass that schema with settled, before any of its fields is read, every value at a field PLAN_SCHEMA marks as a repository path passes isRepositoryPath, the molt.sh files rule, before computeWave, its steps pass computeWave, its trunk_freshness equals the facts, its branch, its base and each versioning.artifact_files path also pass isGitIdentifier, no validation_commands entry is blank or holds a line break or another control character, each refusal naming the entry and its reason, when the facts were taken on a branch other than trunk its branch equals that branch, and its branch matches ^(feature|bugfix|hotfix|refactor|chore|docs|test|ci)/[a-z0-9]+(-[a-z0-9]+)*$, the Branch Taxonomy and Branch Naming of workflow.md, and its title, cleaned as the pull request title is, does not start with a commitTypeMap() value, an optional parenthesized scope, an optional ! and a colon, and buildTitleText(plan), the text the pull request title carries after its type, is not empty, each a refusal with a fixed message that names no title text; each problem, a planner\'s blocked outcome among them, pauses through stopDelivery with isReplan true, a result that is not an object stops the run as no result, and a null one, an agent failure, adds the describeNoResult sentence once and ends the run.' },
    { id: 'SD-09', step: 'Plan', check: 'runPlanningPass', rule: 'Planner questions resolve through decide() kind planner_question and the plan through kind plan_acceptance; a pass puts its asks in one pause and the reply goes to a revise pass whose settled enum holds the shown labels Q1..Qn, where only the keys of the shown questions named in settled count as answered; once that revise passes the plan check, and before any rescope, the reply goes into run.answerLog with the settled labels it names, [] when it names none; a plan acceptance is shown only when no other ask is open, and once settled the shown plan result runs; a settled plan_acceptance, remediation_plan_acceptance or trunk_stale question back in its pass is a terminal cause that ends the run blocked as a workflow defect with no pause; there is no pause limit, so a question still open after any number of rounds pauses again; a plan, revise or rescope problem reaches stopDelivery with isReplan true through describeUnusableResult, so a null result, an agent failure, ends with the run_again Next line and any other unusable result pauses with the fix line brief, its reply starting a new pass; a revise that fails the plan check first logs its reply with settled [], so the stop asks the next round.' },
    { id: 'SD-10', step: 'Plan to branch', check: 'resolveTrunkFreshness', rule: 'Trunk freshness fresh gives fresh and no_remote gives skipped; every other value resolves through decide() kind trunk_stale, where a take gives stale and is listed and an ask pauses.' },
    { id: 'SD-11', step: 'Plan to waves', check: 'resolveExternalEffects', rule: 'Before the first wave each irreversible effect a step declares asks through decide() kind external_effect with its summary as verbatim data, shown whole through encodeUntrustedText in a question that names no step id; an effect question the reply settled is not asked again, one it did not settle or whose summary changed is asked again before any wave, and reversible effects are listed in the final message.' },
    { id: 'SD-12', step: 'Branch', check: 'checkBranchRelay', rule: 'The branch runner runs the create-working-branch command with --base, --branch (the plan branch), --classification, --trunk-freshness and --trunk, those values in its command block only, and its stdout parses with the create-working-branch spec, with a branch line equal to the plan branch; a blocked relay, a create-working-branch refusal, and a branch other than the plan branch are terminal causes that end the run, any other unusable relay pauses through stopDelivery with isReplan true and the fix line brief, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line.' },
    { id: 'SD-13', step: 'Branch', check: 'needsBranchReplan', rule: 'A branch step that switched onto an existing branch the facts were not taken on, or whose commit differs from the facts head, sends the run back through facts and planning before any wave; a second switch in the run is a terminal cause that ends the run through stopDelivery.' },
    { id: 'SD-14', step: 'Waves', check: 'runPlanWaves', rule: 'Each wave comes from computeWave over the plan steps and the done ids; its workers run in parallel() with their step, wave_scopes, plan_summary and git blocks as data under the boundary sentence and the data line, the file scope and git rules being those of drone.md, changeling.md and safety-rails.md; the loop reads every worker outcome before the wave commit, a null result counting as blocked with a reason that names the agent failure in the describeNoResult sentence and next action run_again, passes the one describeBlockedWave cause of a blocked wave to runCommitStep, which stops with it through stopDelivery as a replan, and handles needs_replan only after a successful commit.' },
    { id: 'SD-15', step: 'A wave to its commit', check: 'runCommitStep', rule: 'After every wave the commit runner runs the molt command with --trunk and --inputs .hivemind/molt-inputs-<stem>-<label>.json (SD-74), its inputs_file block content holding the commit type mapped from the classification, breaking, the subject of SD-66 and the wave files, every key a field molt.sh takes; its stdout parses with the molt spec with a branch line equal to the plan branch, and a blocked commit gives a cause of one lead line naming its blocker, then at most maxListedItems() outside lines and a count of the rest; through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence and next action run_again, and any other unusable result keeps the fix line; the wave, fix and review steps read their own result before the commit and pass its causes to runCommitStep, which stops through stopDelivery, isReplan true for a wave and false for a gate step: a commit problem with the step causes then the commit cause, and a made commit with step causes with those causes and the line naming the commit as an end line only when committed is true, so a commit stop never hides a step cause and each agent failure sentence shows once; a commit relay that held passes its commit line to observeHead (SD-72) before any stop; a blocked commit relay, the commit script refusing, and a branch other than the plan branch are terminal and end the run, an agent failure ends it, and every other commit or step stop pauses, so runCommitStep returns {values}, {result}, {replan} or {rerun: true}.' },
    { id: 'SD-16', step: 'Waves', check: 'describeBlockedWave', rule: 'A blocked or failed worker stops the run after the wave commit with one cause: a lead line naming the stop after its wave, then one line per blocked step up to maxListedItems() and a count of the rest, with next action run_again only when every blocked worker says so and agentFailure when any blocked worker had a null result; a wave with an agent failure ends the run, the commit end, when the wave commit made a commit, its own block after the Next line, and any other blocked wave pauses with the commit end as a line of its lead, and the reply starts a new pass that does not count against maxReplans().' },
    { id: 'SD-17', step: 'A wave to planning', check: 'requestStepReplan', rule: 'A needs_replan wave is committed, then the run gathers facts and plans what is left with the done ids reset, at most maxReplans() times; a needs_replan after that asks one step_stop question whose lead names the limit and the worker reasons, and the reply starts a new pass with those reasons that does not count against maxReplans(), so a needs_replan at the limit again asks again.' },
    { id: 'SD-18', step: 'Prompts', check: 'runnerReadOnlySentence', rule: 'Runner prompts carry no request text; the scan and validation drones carry the runner read-only sentence, only the trigger words of the read-only exemption in ${CLAUDE_PLUGIN_ROOT}/agents/drone.md, and no runner prompt carries an exemption, a skill or a tool sentence.' },
    { id: 'SD-19', step: 'Result', check: 'buildRunRecordParts', rule: 'No message and no pull request text lists the commits: the branch and the pull request on GitHub hold them (ADR-0037 decision 2); the pull request body and comment carry every part buildRunRecordParts() returns, in its order: the reversible effects, each gate and every taken decision, the decisions in full there and one line each in chat; and a resume replays every earlier prompt byte for byte.' },
    { id: 'SD-20', step: 'Pause', check: 'pauseDelivery', rule: 'A pause is its lead, then renderQuestions of its asks, a whole block when an ask is exact, with no commit, gate line, taken decision or detail block; a planning pause lead is describePlanLine(plan, outsidePaths); each external_effect ask is exact, so its irreversible effect text shows whole through encodeUntrustedText in every fit tier, and no other ask shows verbatim text, so a plan or remediation plan acceptance shows a short code-built problem and never the plan summary or a pointer to the per-agent results; when the replies fail canCarry the run ends blocked through finishOpenQuestions, stop reason reply_size, and when canShowWhole is false, stop reason exact_text_size, and runs nothing further; that stop is one cause with next action answer through finishDeliveryBlocked, so the message is its lead, the Next line nextStepLine(\'answer\'), the open questions, the branch line naming the encoded branch and its head once a wave ran, then the reversible effects and the taken decisions one line each; these are the only open question stops.' },
    { id: 'SD-21', step: 'Version check', check: 'checkVersionRelay', rule: 'When plan.versioning.artifact_files is not empty, the validate drone also invokes hivemind:bump-type once under the version check sentence, with a JSON version block of base, the pass facts trunk_commit, bump_trigger and no_bump_match from plan.versioning, and version_files, and nothing else, and the validate schema requires its relay in a version field under passed, failed and not_run and allows it under blocked; the relayed stdout parses with versionCheckRoutingSpec(), whose keys are the bump-type.sh OUTPUT keys in order with counts as a block, and passes isConsistentVersionRelay; a match holds the gate with a note naming the version, also in a pass after a replan with no fix and no stop; a blocked, malformed or unusable relay pauses through stopDelivery and the reply runs the head check (SD-73), then validation again with the next count, while a null validation result still ends the run; with no version files the prompt and schema are as before and no bump-type run happens.' },
    { id: 'SD-22', step: 'Version question', check: 'askVersionQuestion', rule: 'While run.versionAnswer is unset, a version_check of undetermined or unreadable asks version_bump_indeterminable with no decide() call and a code-built brief that fits BRIEF_SCHEMA with strength none: for undetermined the options are a major, minor and patch bump and no bump, each naming the version it gives when trunk_version is known, and for unreadable the problem names the formats the check reads and the options keep the branch version or set the version the reply names; the reply becomes run.versionAnswer and runs one fix round with the version_files and user_answer blocks and no resume note, outside decide() and the round limit, and never a new pass; once run.versionAnswer is set no later version check of the run fails or asks, and the gate note says the version is as the user replied.' },
    { id: 'SD-23', step: 'Tail asks', check: 'askTail', rule: 'Every ask after the last wave pauses through pauseDelivery with its lead and its one question, and pushes nothing: askTail pauses with the lead it is given, and with none with a code-built line that every plan step is committed on the encoded branch, naming the head; its reply goes into run.answerLog through buildAnswerEntry with question the lead text and the questions and settled [], since no revise reads a tail reply; tail rounds share run.answerLog and the answers round numbering with planning rounds, so a resume replays every earlier agent from cache and takes the reply at the ask; the Next line of an open question stop never offers a pull request from commits a gate did not hold on.' },
    { id: 'SD-25', step: 'Validate', check: 'readValidateOutcome', rule: 'A hivemind:drone on its default model runs validation once per head and edits nothing, and no commit runner follows it, so a dirty path it leaves is refused by the next commit runner or by the dirty check of hivemind:open-plan-pr; when plan.validation_commands is not empty its prompt is the task line, the validation commands sentence, which names no governance doc and makes running each command of the inputs block once, in order and in the foreground, its whole task, not a Worker Self-Check, and the runner read-only sentence, with the commands in a JSON inputs block, and it returns passed, failed with the failures as text, or blocked, as VALIDATE_COMMANDS_SCHEMA says; when the list is empty its prompt is the task line, the validation task sentence, which names the Validation Procedure clause of definitions.md, and the runner read-only sentence, and VALIDATE_SCHEMA also offers not_run, so an empty list never skips validation; passed or not_run holds the gate, not_run is listed, and blocked or a malformed result pauses through stopDelivery, whose reply runs the head check (SD-73), then validation again with the next count, and through describeUnusableResult a null result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line, and any other unusable result keeps the fix line.' },
    { id: 'SD-26', step: 'Fix rounds', check: 'runFixRound', rule: 'A failed validation resolves through decide() kind validation_remediation; each taken round is a hivemind:drone under the validation fix sentence, the validation fix task trigger of drone.md, with the failures as data under the boundary sentence, and it reports its files as FIX_SCHEMA says; the commit runner commits exactly those files with the plan commit type; a failed result is kept for the head it ran on, so after a fix round that commits nothing no validate agent runs and the next validation_remediation decision takes the kept failures, counting toward maxFixRounds(); after maxFixRounds() rounds a failure pauses asking, and the reply starts a new pass; a fix round is read before its commit, and a blocked one gives runCommitStep one cause, its reason with its next action, a null fix result naming the agent failure with next action run_again and agentFailure, which ends the run after the fix commit, while any other blocked fix round or fix commit stop pauses there with the line naming the commit only when one was made, and the reply runs the head check (SD-73), which clears the kept failures, so validation runs again with the next count; while run.versionAnswer is unset, a version mismatch joins a code-built line naming expected_version and the bump to the command failures and gives the fix prompt the version_files block, a version-only failure runs its fix round with no decide() call, counted toward maxFixRounds(), and at the limit pauses through stopDelivery, whose reply resets the round count and runs the head check, then validation again, never a new pass, and fix labels count every fix round of the pass.' },
    { id: 'SD-27', step: 'Gates', check: 'runGates', rule: 'A gate holds only for the commit its step ended on, and validation, which has no commit runner, ends on the head it ran on; a step ending on a commit other than the head the gates last checked sends the run back to the first gate to rerun each gate that held on an earlier commit, each going back resolves once through decide() kind gate_rerun naming only the gates that rerun, after maxGateReruns() of them the run pauses asking and the reply starts a new pass, and the run finishes complete only when every configured gate held on one commit, naming it.' },
    { id: 'SD-28', step: 'Gate labels', check: 'gateLabel', rule: 'Gate step labels come only from the pass, the gate step and its run count (validate-P-N, fix-P-N, fix-commit-P-N, review-P-N, review-commit-P-N), so every label is unique and a run again replays every prompt byte for byte.' },
    { id: 'SD-29', step: 'Decisions', check: 'resolveDecision', rule: 'Every decide() kind main.js uses, review_question and high_severity_rejection among them, is a *_KIND const and a hard stop or a row of the autonomy table whose resolved_at names a standard-delivery site; step_stop, the kind of the one undecided question stopDelivery asks with no decide() call, is a *_KIND const too, and its row surfaces at every level and is resolved at standard-delivery.stop.' },
    { id: 'SD-30', step: 'Launch', check: 'readLocalReview', rule: 'The local_review launch arg is absent, true or false; absent means configured, and any other value stops the run before any agent call.' },
    { id: 'SD-48', step: 'Launch', check: 'readDraft', rule: 'The draft launch arg is absent, true or false; absent means false, any other value stops the run before any agent call, and the value is the draft field of the open-plan-pr inputs_file block.' },
    { id: 'SD-31', step: 'Gates', check: 'configuredGateIds', rule: 'With local_review false the local review gate is not configured: it never runs, never stops the run, never counts as held, the complete message names it as not configured in its gates line, and the pull request body and comment list it as not configured for this run.' },
    { id: 'SD-32', step: 'Validation to local review', check: 'buildReviewPrompt', rule: 'Once validation holds, hivemind:local-reviewer gets base, working_branch, trunk, max_iterations 10 and caller_validates true in a JSON inputs block under the boundary sentence and the data line, with no request text and no rule of local-reviewer.md, label review-P-N and phase Review; a review run after a reply to its question also gets user_answer, the question and the reply, in that block, and the data line names that reply as the user decision; a review run after a taken call gets user_answer with decided_by run, and the data line names that reply as the run decision, not the user\'s.' },
    { id: 'SD-33', step: 'Review result', check: 'describeReviewProblem', rule: 'The review result fits REVIEW_SCHEMA, whose fields are the local-reviewer Output Contract fields with each Codex-derived text field labelled as able to carry external content, finding_id and each rejected finding_id the one finding id shape of findingIdField(), maxLength 64 and pattern ^[0-9a-f]{8,64}$, recommendation_text with maxLength 200 and allowed empty, blocker with maxLength 300, hypothesized_root 300, root_class 100, same_framing_rationale 600, classification 100, file 400 and title 300, field_excerpt 200 and pattern_category one of P1, P2, P3 or P4, user_question an object of found and ask with maxLength 200, options of 2 to 4 items of id A, B, C or D and summary with maxLength 160, recommendation of option_id A to D, strength strong, weak or none and why with maxLength 200, each text labelled so, and the required gate of the booleans irreversible and architectural, with no other key, the required rejected_findings a list of at most 50 objects of finding_id, title and record, each labelled so, with no other key, and it carries every field its exit_reason names and no conditional field that only another exit_reason names; each conditional list field holds at least one entry and has maxItems, signals_fired and signals_observed 10, conflicting_findings, cluster_files and cluster_ids 20, each cluster_files entry at most 400 and each cluster_ids entry at most 64 code points, and buildReviewFieldSchema throws on a list entry with no maxItems; every count is zero or more, and no conditional field is a count; a user_question whose option ids are not A, B, C, D in that order, which refuses a repeated id, or that recommends no option of its own is refused too; any other result pauses after the review commit with one step_stop question, and the reply runs local review again with the next count, its commit runner reading the head (SD-73); through describeUnusableResult a null result, an agent failure, ends the run, adds the describeNoResult sentence once and the run_again Next line, and any other unusable result keeps the fix line.' },
    { id: 'SD-34', step: 'Local review to its commit', check: 'runReviewGate', rule: 'Whatever the reviewer returned, the commit runner then runs with an empty file list and stops the run on any edit left behind, and the review gate holds on the commit it reports; describeReviewProblem reads the review before the commit and its cause goes to runCommitStep, so an unusable review is never hidden by a commit stop, and a null review commit result gives the run_again Next line only when no cause with the fix line leads; a non-null unusable review pauses after the review commit, and the reply runs local review again with the next gateLabel count, its commit runner reading the head (SD-73).' },
{ id: 'SD-35', step: 'Review routes', check: 'localReviewRoutes', rule: 'localReviewRoutes() maps every exit_reason of the local-reviewer Output Contract and nothing else, and clean holds the gate. The exits it routes to hold or diminishing are the exits workflow.md (PR Requirements) names as holding, and only the diminishing ones carry its taken condition. The local_review transitions of standard-delivery.json route the same exits: hold to the pr_confirm user gate, diminishing to diminishing_returns_decision, whose only transition to a state that is not terminal is taken, into pr_confirm. Only local_review clean, diminishing_returns_decision taken and local_review_decision skipped transition into pr_confirm, and pr_confirm approved is the only transition into open_pr. Every other pr_confirm and diminishing_returns_decision outcome ends at a terminal state that never reaches open_pr. localReviewRoutes() routes injection-suspect to stop, max-iterations-reached and break-fix-break to stop_replan and blocked to stop_rerun; the local_review transitions stay as they are, so every stop exit, each asked one included, ends at a terminal state there that never reaches open_pr.' },
    { id: 'SD-36', step: 'Review stops', check: 'describeReviewStop', rule: 'max-iterations-reached, break-fix-break, injection-suspect and blocked stop with one line naming the exit and its cause, the head, the iterations and the open finding count, then at most one detail line built in code: break-fix-break says the fix conflicts with the count of earlier findings and shows no entry text, injection-suspect names the short finding id and the category in its line and shows the whole excerpt encoded in its detail line, and blocked quotes the blocker with a limit equal to its maxLength 300, so a valid blocker is never cut; through stopDelivery, injection-suspect is terminal and ends the run blocked, max-iterations-reached and break-fix-break pause with that stop as the lead of one step_stop question whose reply starts a new pass, outside maxReplans(), with replan data carrying the review projected by projectReplanReview(), and blocked pauses the same way and its reply runs local review again with the next count, its commit runner reading the head (SD-73).' },
    { id: 'SD-37', step: 'Review questions', check: 'askReviewQuestion', rule: 'user-input-required and high-severity-rejection resolve through decide() on a brief built in code from the reviewer option ids, recommendation, strength and gate, with safety false and the recommended option reversible unless the gate says irreversible, so every text is code-built and a valid review never asks as malformed_brief; a take, an agreed call that is reversible and not architectural, never pauses and never touches run.answerLog, lists the call in run.taken by its short finding id with the encoded ask and the encoded summary of the chosen option, and reruns the review gate; an ask, the gate irreversible or architectural, strength none or a surface cell, pauses the run with the lead Local review on commit, the head, the finding by the first 8 code points of its finding_id and the encoded found, then the reviewer question: its problem the encoded ask, its options the reviewer options with encoded summaries, and its recommendation the reviewer option_id and strength with the encoded why, no option and no strength from code, with its ask reason from decide(); the rerun review gets that lead and the question as user_answer.question.' },
    { id: 'SD-38', step: 'Diminishing returns', check: 'resolveDiminishingReturns', rule: 'diminishing-returns resolves through decide() kind diminishing_returns_exit: a take holds the gate and is listed, and an ask pauses the run and the reply starts a new pass.' },
    { id: 'SD-39', step: 'Local review to planning', check: 'requestReviewReplan', rule: 'planner-escalation and root-cluster-suspected resolve through decide() kinds planner_escalation_routing and root_cluster_routing; an ask pauses the run and the reply starts a new pass, and a take starts a new pass through the facts step with replan data projected by projectReplanReview() to exit_reason and only the fields reviewExitFields() names for it, so rejected_findings, ledger_path and the counts never reach the planner, counted against maxReplans(); a take at maxReplans() pauses with one step_stop question, and its reply starts a new pass with that projected review that does not count; every such replan reason asks for the remediation of what the review block reports, and none names a zoom-out.' },
    { id: 'SD-40', step: 'Remediation plan', check: 'resolvePlanAcceptance', rule: 'Once local review sent the run back to planning, which it reads from the run\'s taken planner_escalation_routing or root_cluster_routing decision, every later plan acceptance resolves through decide() kind remediation_plan_acceptance, auto at high and balanced and surface at low; its brief gate copies plan.remediation_gate.promotion_gate (irreversible, architectural, safety) whole, with gate.architectural also true when grows_surface or repeats_surface is true, and its problem names each of the five flags that holds, so a flagged plan asks with gate_irreversible, gate_architectural or gate_safety through the pause and revise path and a plan with a clean gate is taken and listed at the default level, unless a plan file lies outside the scope limits, which asks it with no_recommendation.' },
    { id: 'SD-41', step: 'Gates', check: 'resolveGateRerun', rule: 'A commit the reviewer makes sends the run back through validation, and a commit made after local review held sends it back through validation and local review.' },
    { id: 'SD-42', step: 'Gates to the PR', check: 'buildPullRequestPrompt', rule: 'Once every configured gate held on one commit H, a haiku runner runs the open-plan-pr command once, with label pr-P and phase PR, one runner call inside the gate loop, and each reply to a pause of that step runs the head check (SD-73), then the step again under label pr-P-N, N from 2, with the same inputs when the head did not move and after the gates rerun when it did, with a command of only --head (the plan branch), --base (the plan base), --expect-commit H and --inputs .hivemind/pr-inputs-<stem>-<label>.json (SD-74) and an inputs_file block content of only title, body, comment and draft (the draft launch arg); it is the only push the workflow makes, so every push carries --expect-commit.' },
    { id: 'SD-44', step: 'PR title', check: 'buildPullRequestTitle', rule: 'The title is one line with no control character, plain text with no Markdown wrapper, built from the plan commit type, the breaking marker and plan.title, never from the plan summary, at most maxTitleLength() code points including that prefix, cut at a word boundary only when longer, and never ending in an ellipsis or inside a bracket it opened; for a plan that passed the plan check the text after the prefix, buildTitleText(plan), is never empty (SD-08).' },
    { id: 'SD-45', step: 'PR body and comment', check: 'buildPullRequestTexts', rule: 'The body holds the plan summary and the run record, and the comment its lead and the run record, where the run record is every part buildRunRecordParts() returns, in its order: the reversible effects, each gate with its result and the commit it held on or not configured for this run, and every taken decision, a taken local review call with the fixed texts of reviewCallTexts() and no finding id; neither carries a control character other than newline and tab or any reviewer text, each of the summary, the reversible effects and the decisions sits in its own fenced block whose fence is one backtick longer than its longest backtick run, at least three, the gates and the comment lead stay plain, the decisions go compact when a text would pass maxPullRequestTextLength() characters, a text still too long is a terminal stop that ends the run blocked naming its size before any push, and a title, body or comment that holds a forbiddenSubjectTexts() string in any case is a terminal stop that ends the run blocked naming that text before any push.' },
    { id: 'SD-46', step: 'PR relay', check: 'checkPullRequestRelay', rule: 'The relayed stdout parses with openPlanPrRoutingSpec(), whose keys are the open-plan-pr.sh OUTPUT keys in order and whose warning holds only the script fixed texts, head_ref_oid equals H, and commented is true exactly when created is false; a head_ref_oid other than H is a terminal stop that ends the run blocked; a blocked, malformed or other non-null unusable relay pauses through stopDelivery with one step_stop question naming the pull request step, and the reply runs the step again; through describeUnusableResult a null result, an agent failure, ends the run, adds the describeNoResult sentence once and the run_again Next line, and any other unusable result keeps the fix line.' },
    { id: 'SD-47', step: 'Result', check: 'finishDeliveryComplete', rule: 'The run finishes complete with pr {url, head_ref_oid, created}, and the final message is one line naming the pull request opened or pushed to and its commit, one line naming the gates that held and any gate not configured, the warning line when there is one, the rejected findings block, then the reversible effects and the taken decisions, one line each, and no commit list.' },
    { id: 'SD-49', step: 'Prompts', check: 'addResumeNote', rule: 'Once run.answerLog is not empty, every agent prompt carries resumedReplySentence() as its second line but the scope, plan and revise prompts and the review and fix prompts with user_answer, which carry the replies in data blocks and not the sentence; no prompt sent before the first reply carries it, and no other prompt carries reply text.' },
    { id: 'SD-50', step: 'Relays', check: 'describeRelayBlocker', rule: 'Every step- or script-written diagnostic or name a message shows goes through encodeUntrustedText, while planner prose rendered by lib/brief.js shows whole through renderText, one line with no control, line separator or bidi character, so it never starts a line of the question structure, and each option shows the letter optionLabel gives its position; a blocked relay quotes its last non-blank blocker line, else its first two non-blank stderr lines, else gives no reason, each one line cut at a sentence or word boundary to maxExcerptLength() code points, a step blocker goes through describeReason, one line quoted whole up to maxReasonLength() code points and cut at a boundary past it, each cut quote followed by the cut mark, and the text starts with a capital letter after a full stop and stays lower case after a colon; every blocked lead the facts, branch, wave, commit and gate steps build is one line naming the step and its cause, and capItemLines() shows at most maxListedItems() delivery stop, dirty path or blocked step lines, then a count of the rest.' },
    { id: 'SD-51', step: 'Result', check: 'finishDeliveryBlocked', rule: 'Every blocked result is finish over its causes, and no caller builds a lead or a Next line: finish puts buildStopBlocks of the causes first, the lead, then nextStepLine() with the lead cause next action as a whole block, then one block per later cause; finishDeliveryBlocked then adds one block per end line, one line naming the encoded branch and its head only once a wave ran, then the reversible effects and the taken decisions, one line each; an open question stop and a resume of another build are one cause with next action answer; no block carries shorten, a lead over maxBlockedLeadLength() code points has as its compact form the cutAtBoundary prefix of at most those code points, so it never cuts mid-word, and finish throws only when causes are not given exactly for a blocked outcome and when a complete outcome has no blocks.' },
    { id: 'SD-52', step: 'Question keys', check: 'questionKey', rule: 'A question key holds its kind, its scope and its rendered text: the scope is the pass for planner_question, the pass and the whole plan for both plan acceptances, and run for trunk_stale and external_effect.' },
    { id: 'SD-53', step: 'Message shape', check: 'buildRecordTailBlocks', rule: 'Every pause is a one-line lead, but a step_stop lead holds each cause line and end line, then the questions, and the reply line last; every run end is its lead, followed by the Next line when blocked; no message shows a commit list, a criticality or ask-reason line, a detail block, the plan summary or a word for word section but for an irreversible effect, no pause shows a taken decision, each taken decision takes one line, every cut quote ends at a sentence or word boundary followed by the cut mark, no full finding id appears, and each message stays within the fixed bound the test states.' },
    { id: 'SD-54', step: 'Next action', check: 'buildStopBlocks', rule: 'WORKER_SCHEMA, the fix gate edit schema, VALIDATE_SCHEMA and VALIDATE_COMMANDS_SCHEMA each carry an optional next_action of fix_cause or run_again, only with outcome blocked; there are three next actions, and answer is set only by code, never by an agent or a schema; nextStepLine() starts with Next: and points at no cause the lead does not name; it maps fix_cause or no value to the fix line, run_again to a fixed line saying nothing in the repo needs a fix, and answer to the line saying to run the request again with the answers in it; one rule covers every step: a null result from any agent() call, an agent failure, gets the describeNoResult sentence once, only through describeUnusableResult, next action run_again and agentFailure true, which no other code sets, and a non-null unusable result keeps the fix line; buildStopBlocks puts the causes of a stop with the fix line or the answer line first, then the run_again ones, each in step order, and its Next line is that of its first cause, the fix line unless every cause is run_again, so a lone agent failure ends with the sentence in its first block and nextStepLine(\'run_again\') as its second, and a compound stop shows every cause with each agent failure sentence once; a blocked wave uses run_again only when every blocked worker says run_again.' },
    { id: 'SD-55', step: 'Rejected findings', check: 'buildRejectedFindingsBlock', rule: 'When the review that held the gate lists rejected_findings, the review gate note adds the code-built count of findings rejected under recorded decisions, which the pull request body and comment carry with no rejected-finding text, and the final complete message carries a chat-only rejected findings block right after its gates line and any warning line: one heading line with that note, then one line per rejected finding with only the short id, the first 8 characters of its finding_id, encoded by encodeUntrustedText; an empty list adds nothing.' },
    { id: 'SD-56', step: 'Step results', check: 'buildTaggedSchema', rule: 'Every step result schema whose fields depend on its outcome or exit_reason is built by buildTaggedSchema; a result that carries a field of another outcome, or lacks one its outcome requires, fails its check and blocks the step that reads it, and each agent gets the schema through toAgentSchema, with no anyOf.' },
    { id: 'SD-57', step: 'Tail replies', check: 'replanFromTailAsk', rule: 'A reply to a local review question reruns the review gate on the current head with the next gateLabel count and user_answer {question, reply}, and a taken local review call does the same with user_answer {question, reply, decided_by run}, the reply the recommended option id, and the commit runner and localReviewRoutes() apply as for any review run; when that review returns planner-escalation or root-cluster-suspected and its routing is taken, the replan counts against maxReplans(); a reply to a version question runs one fix round and starts no pass; a reply to any other tail ask starts a new pass through the facts step that does not count against maxReplans(); a reply to a facts, scan, scope, plan or branch stop of a pass whose replan data carries a review keeps that review in the replan data of the new pass (keepReplanReview), and a pass no review started gets none; no replan data carries an answer, since the answers block holds it.' },
    { id: 'SD-58', step: 'Bounded fields', check: 'describePlanLine', rule: 'No message cuts an agent value: every agent-written string a message shows comes from a step-schema field with maxLength and shows whole, or no message shows it; a planning pause lead is describePlanLine(plan, outsidePaths), one line of the encoded branch, which plan-schema.json bounds by maxLength 200, the step count, the distinct plan path count and digest.change made one line, then any outside paths, which plan-schema.json bounds by maxLength 400, each encoded whole, and the external effect question names no step id, so no step id is cut; every local review string a message shows has a bound in REVIEW_SCHEMA, whose every list has maxItems, and every message stays within a fixed bound when every unbounded agent field (plan.summary, worker summary, validate failures, and the review strings with no maxLength) holds 5000 characters.' },
    { id: 'SD-59', step: 'Scope', check: 'runScopeStep', rule: 'Every pass runs the scope step once, after the facts step and the scan and before planning: hivemind:cerebrate on SCOPE_MODEL sonnet at effort high, with label scope-P and phase Scope; after the revise of answer round R, unless the reply settled the shown plan acceptance, the pass scopes again with label scope-P-R, whose scope replaces the pass scope for the acceptance check and every later revise prompt of the pass, so a resume replays both from cache; runScopeStep returns {scope} or {problem, nextAction}, which stops through stopDelivery with isReplan true, and through describeUnusableResult a null scope-P or scope-P-R result, an agent failure, adds the describeNoResult sentence once and ends the run with the run_again Next line, and any other unusable result pauses with the fix line brief.' },
    { id: 'SD-60', step: 'Scope prompt', check: 'buildScopePrompt', rule: 'The scope prompt is one task line asking to scope the request for its planner in Scope Mode, then boundarySentence(), dataBlocksSentence(), the facts block and the request block; once run.answerLog is not empty, settledAnswersSentence(), which calls settled only what the settled labels of each entry name, takes the place of the data line and the whole log follows the request block in an answers block, and the prompt never carries the resume note, so a scope prompt sent before the first reply equals that of a run with no answers.' },
    { id: 'SD-61', step: 'Scope result', check: 'buildScopeSchema', rule: 'SCOPE_SCHEMA holds documents[] of {path, line} with an integer line, paths[] of {path, exists, drift} and limits[] of path strings, all three required, documents holding at most 10 entries and paths and limits at most 30 each by maxItems, each string field starting with externalLabel(), each path field and limit marked with repositoryPathMark() and every string with a maxLength.' },
    { id: 'SD-62', step: 'Scope result', check: 'keepRepositoryPathEntries', rule: 'A scope result that fails SCOPE_SCHEMA pauses the run before planning, saying the scope step returned a result it could not use; a path that starts with the facts root line and a slash is first made relative to that root, and a root of none converts nothing; an entry whose path then fails isRepositoryPath is dropped from the scope and does not stop the run; a limit is made relative the same way and loses a trailing slash, but is never dropped; a re-scope result that fails SCOPE_SCHEMA pauses the same way, after the reply of its round is logged; an empty scope lets planning go on.' },
    { id: 'SD-63', step: 'Scope to planning', check: 'buildPlanPrompt', rule: 'The plan and revise prompts carry the checked scope as a scope data block right after the request block, a revise prompt after a re-scope carrying the re-scope result, and the scope never reaches a message, the pull request texts or a worker prompt.' },
    { id: 'SD-64', step: 'Scope Mode', check: 'scopeOptions', rule: 'Scope Mode is the ### Scope Mode section of ${CLAUDE_PLUGIN_ROOT}/agents/cerebrate.md, which owns what a scope holds, and the scope step sends the planner agent there by name only.' },
    { id: 'SD-66', step: 'Commit subject', check: 'toCommitSubject', rule: 'Every commit inputs_file block carries a subject built by code, so the runner reads no git state to write one: a wave of one step gives its outcome, a wave of several gives their ids then the first outcome, made one line and cut by cutAtBoundary to at most maxSubjectLength() 72 code points; the fix round and review commits have fixed subjects; a derived subject that is blank, holds !: or a BREAKING CHANGE marker, or holds an attribution string the molt SKILL.md forbids falls back to a fixed subject naming the wave; every subject passes the molt.sh subject rules.' },
    { id: 'SD-67', step: 'Answer log', check: 'buildPlanPrompt', rule: 'Each reply a pause takes goes once into run.answerLog as {question, settled, reply}, question the pause lead and renderQuestions of the shown asks, settled what buildAnswerEntry derives from the checked revise of its round: the shown Q labels that revise names, in shown order, or [] when it names none or no revise reads the round; every later plan prompt, after a branch, step, tail or review replan alike, carries the whole log in an answers block, and a revise prompt the entries of earlier rounds, and the data line calls settled, never asked again or reversed, only what the settled labels of an entry name.' },
    { id: 'SD-68', step: 'Resume build', check: 'readLaunchInputs', rule: 'resume_args carries build, the BUILD_ID of the script that paused; a resume whose build is absent or differs stops blocked before any agent call as one cause with next action answer, whose Next line asks to run the request again with the answers in it, not to fix anything, and a resume of the same build replays every earlier prompt byte for byte.' },
    { id: 'SD-69', step: 'Scope limits', check: 'listOutsidePaths', rule: 'When the checked scope sets limits, a plan path, which listPlanPaths gives as every value at a PLAN_SCHEMA field the repository path mark names, the step files and version files, that neither equals a limit nor sits under limit plus a slash makes the plan or remediation plan acceptance brief recommend with strength none, so decide() asks it no_recommendation at the default level, its problem naming their count only when it fits the brief bound and the pause lead describePlanLine(plan, outsidePaths) naming up to maxListedItems() 5 of them, each encoded whole, then the count of the rest; a limit that fails isRepositoryPath matches no file, so it asks; empty limits leave the brief as it was; the limits come only from the scope step, so a later pass whose limits still leave a file outside asks it again; validation fix round and local review edits are not plan paths and are outside the limits.' },
    { id: 'SD-70', step: 'Stops', check: 'stopDelivery', rule: 'stopDelivery(causes, run, endLines, isReplan) ends the run through finishDeliveryBlocked when any cause has terminal true or agentFailure true, mixed causes included; otherwise it asks one undecided question of kind step_stop through askTail, whose lead is the cause problems in buildStopBlocks order, then the end lines, one per line, with the cutAtBoundary prefix of maxBlockedLeadLength() code points as its compact form when longer, and whose code-built buildStepStopBrief fits BRIEF_SCHEMA with one option and strength none, says to fix what stopped the run then reply with every change committed, or that nothing in the repo needs a fix when every cause is run_again, and says whether the reply takes the stopped step again or plans again; a pause returns {result}, and a reply returns {replan: {reason}} when isReplan, a new pass that does not count against maxReplans(), else {rerun: true}: the gate loop takes the stopped step again, reading the head first per SD-73; the built script calls finishDeliveryBlocked only in stopDelivery, finishOpenQuestions and the launch end of runDelivery.' },
    { id: 'SD-71', step: 'Runner retry', check: 'runRunnerRelay', rule: 'The facts, branch, commit and pull request runners call agent() through runRunnerRelay: a relay that fits RELAY_SCHEMA with outcome blocked and a stderr isTransientFailure names runs once more under label <label>-retry with the prompt built for that label: the facts and branch prompts are identical, and the commit and pull request prompts differ only in the inputs path, so a retry never writes the first call\'s file; that relay is read as the first would be; a malformed relay, a non-transient block and a null result are never retried, and no step call retries more than once.' },
    { id: 'SD-72', step: 'Head', check: 'observeHead', rule: 'observeHead(run, commit, branch) is the only code of the built script that writes run.head, run.branch or run.headRound: it sets run.head to commit, run.branch to branch and run.headRound to the run.answerLog length; runCommitStep feeds it the commit of a checked molt relay, and runDeliveryPass the commit of a checked branch relay after needsBranchReplan and before any wave of each pass; the run keeps no commit list.' },
    { id: 'SD-73', step: 'Head check', check: 'runHeadCheck', rule: 'Every reply adds one entry to run.answerLog, so the head is unread exactly when run.headRound is behind run.answerLog.length, whatever route the reply took; while the head is unread, the gate loop runs one head check before validation or the pull request step: runCommitStep with an empty file list, stepName head and label head-P-N, N counting gates.runs.headCheck over the pass, so molt reports the head of the working branch with committed false, and it clears every kept validation failure; local review gets no head check, since its commit runner, the same empty-list molt run, reads the head; a gate holds only while the head is read; a malformed head check pauses and its reply runs head-P-N+1, a transient block retries once under head-P-N-retry, a refusal of it is a commit-script refusal and ends the run, a null result ends it, and any other run end it returns is returned as is; when the head moved the gates that held on the old head go through the gate rerun of SD-27, else the same step, gate or pull request, runs again.' },
    { id: 'SD-74', step: 'Runners', check: 'describeCommandStop', rule: 'The facts, branch, commit and pull request runners are hivemind:synapse on RUNNER_MODEL haiku, and the scan, validation and fix rounds are hivemind:drone; a runner prompt is its task line, dataBlocksSentence(), a command block holding the one command line of buildRunnerCommand, and for the commit and pull request runners an inputs_file block of {path, content}, whose block names and {plugin-root} placeholder are the words of ${CLAUDE_PLUGIN_ROOT}/agents/synapse.md, {plugin-root} being its only placeholder; the inputs path is built in code from the stem runFactsStep sets from each checked facts relay plus the call label, so no two calls of one run or of two runs share a path and a resumed run rebuilds the same path; a pass with no stem has no path, and its --inputs word is a terminal command stop; the commit and pull request steps check the words for both the call label and its retry label; no runner prompt carries a commit or push grant, since synapse commits and pushes under its standing grant in safety-rails.md (Commit Authority), bounded by the hook; before the call each step checks its command words with describeRunnerWordProblem, the value classes of the synapse gate hook, and a word outside its class is a terminal cause naming its flag and never its value, so no runner call is made; every command the engine builds is an exact form ${CLAUDE_PLUGIN_ROOT}/hooks/synapse-gate.sh allows for hivemind:synapse.' },
    { id: 'SD-75', step: 'Relays', check: 'readRelayedLines', rule: 'The stdout of the facts, branch, commit and head check, and pull request relays, and of the validation version relay, is read through readRelayedLines with parseRoutingLines; that parser reads only the first line of each spec key at its level, and reads a block line only while its block is open, and a block closes only at the next top-level routing line read, so a line it does not read changes nothing, wherever it sits, before, between, inside a block or after the routing lines, such as a push hint, a code fence, a blank line, agent prose or a repeat of the routing lines (issue 447); the first line of a spec key is read wherever it sits, and a missing required key, or a first line off its pattern, still pauses as malformed routing lines.' }
  ];
}
